return [{
  json: {
    statusCode: 200,
    body: {
      data: [
        {
          id: '11111111-1111-4111-8111-111111111111',
          instrument: 'EURUSD',
          direction: 'BUY',
          entryPrice: '1.0850',
          stopLoss: '1.0820',
          takeProfits: ['1.0900'],
          channelName: 'Synthetic Demo Channel',
          providerName: null,
          status: 'validated',
          receivedAt: '2026-01-15T10:00:00.000Z',
        },
        {
          id: '22222222-2222-4222-8222-222222222222',
          instrument: 'GBPUSD',
          direction: 'SELL',
          entryPrice: '1.2700',
          stopLoss: '1.2740',
          takeProfits: ['1.2640'],
          channelName: 'Synthetic Demo Channel',
          providerName: null,
          status: 'validated',
          receivedAt: '2026-01-15T10:05:00.000Z',
        },
      ],
      meta: { count: 2, limit: 10 },
    },
  },
}];

const statusCode = Number($json.statusCode ?? 200);
const body = $json.body ?? $json;
const data = body && Array.isArray(body.data) ? body.data : null;

if (statusCode < 200 || statusCode >= 300 || !data) {
  return [{
    json: {
      schema: 'pipsync.signal-summary.v1',
      ok: false,
      source: 'read-only-signals',
      httpStatus: Number.isFinite(statusCode) ? statusCode : null,
      notification: {
        previewOnly: true,
        message: 'PipSync signal summary unavailable. Check the read-only API credential and workflow execution log.',
      },
    },
  }];
}

const safeSignals = data.slice(0, 100).filter((item) => item && typeof item === 'object');
const instruments = [...new Set(safeSignals
  .map((item) => typeof item.instrument === 'string' ? item.instrument : null)
  .filter(Boolean))]
  .slice(0, 8);
const buy = safeSignals.filter((item) => item.direction === 'BUY').length;
const sell = safeSignals.filter((item) => item.direction === 'SELL').length;
const latest = safeSignals
  .map((item) => item.receivedAt)
  .filter((candidate) => typeof candidate === 'string' && Number.isFinite(Date.parse(candidate)))
  .sort()
  .at(-1) ?? null;
const message = [
  'PipSync read-only signal summary',
  `Signals: ${safeSignals.length} (BUY ${buy}, SELL ${sell})`,
  `Instruments: ${instruments.length ? instruments.join(', ') : 'none'}`,
  `Latest received: ${latest ?? 'not available'}`,
  'No order was created by this workflow.',
].join('\n');

return [{
  json: {
    schema: 'pipsync.signal-summary.v1',
    ok: true,
    source: 'read-only-signals',
    count: safeSignals.length,
    directions: { BUY: buy, SELL: sell },
    instruments,
    latestReceivedAt: latest,
    redaction: { identifiers: 'omitted', prices: 'omitted', channels: 'omitted', providers: 'omitted' },
    notification: { previewOnly: true, message },
  },
}];
